-- Упражнения книги 19, глава 26 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-read-full', 0, 'c', 'read_full: чтение ровно n байт', 'Один вызов read вправе вернуть меньше байт, чем просили, или быть прерван сигналом. Напишите функцию read_full(fd, buf, n): она читает ровно n байт в цикле и возвращает число прочитанных байт. Меньше n она возвращает только на конце файла (read вернул 0). Ошибку EINTR повторяйте, любую другую ошибку верните как -1 с тем же errno. При n равном нулю к ядру обращаться не нужно. Проверка подменяет read (линковщик, --wrap=read) моделью ядра: она отдаёт данные порциями 3, 1, 5, 7 байт, вставляет EINTR и ошибку EIO, а для других дескрипторов вызывает настоящий read. Всё, что программа печатает, на английском.', '#include <unistd.h>
#include <errno.h>
#include <stddef.h>
#include <sys/types.h>

/* Прочитать ровно n байт из fd в buf.
   Вернуть число прочитанных байт (меньше n только на конце файла)
   или -1 с errno при настоящей ошибке. */
ssize_t read_full(int fd, void *buf, size_t n) {
    return -1;
}
', 'Цикл while (got < n); read(fd, buf + got, n - got); при r < 0 и errno == EINTR сделайте continue; r == 0 — break.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* The model of the kernel: fake descriptors 100..103 serve a text in the portions of a script. */\nstruct fake { const char *data; size_t len, pos; const int *script; int nsteps, step; int calls; };\nstatic struct fake fk[4];\nssize_t __real_read(int fd, void *buf, size_t n);\nssize_t __wrap_read(int fd, void *buf, size_t n) {\n    if (fd < 100 || fd > 103) return __real_read(fd, buf, n);\n    struct fake *f = &fk[fd - 100];\n    f->calls++;\n    size_t cap = n;\n    if (f->step < f->nsteps) {\n        int s = f->script[f->step++];\n        if (s == -1) { errno = EINTR; return -1; }\n        if (s == -2) { errno = EIO; return -1; }\n        if ((size_t)s < cap) cap = (size_t)s;\n    }\n    size_t left = f->len - f->pos;\n    if (cap > left) cap = left;\n    memcpy(buf, f->data + f->pos, cap);\n    f->pos += cap;\n    return (ssize_t)cap;\n}\n\nint main(void) {\n    setup();\n    const char *alpha = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\";\n    static const int s0[] = {3, -1, 1, 5, -1, -1, 7};\n    static const int s1[] = {4, -2};\n    static const int s2[] = {-1};\n    fk[0] = (struct fake){alpha, 36, 0, s0, 7, 0, 0};\n    fk[1] = (struct fake){alpha, 36, 0, s1, 2, 0, 0};\n    fk[2] = (struct fake){alpha, 36, 0, s2, 1, 0, 0};\n    fk[3] = (struct fake){alpha, 10, 0, NULL, 0, 0, 0};\n    char buf[64];\n    ssize_t r;\n    memset(buf, 0, sizeof buf);\n    r = read_full(100, buf, 20);\n    printf(\"%zd %s\\n\", r, buf);\n    memset(buf, 0, sizeof buf);\n    r = read_full(100, buf, 40);\n    printf(\"%zd %s\\n\", r, buf);\n    int calls_before = fk[0].calls;\n    r = read_full(100, buf, 0);\n    printf(\"%zd %d\\n\", r, fk[0].calls - calls_before);\n    errno = 0;\n    r = read_full(101, buf, 10);\n    printf(\"%zd %s\\n\", r, en(errno));\n    memset(buf, 0, sizeof buf);\n    r = read_full(102, buf, 5);\n    printf(\"%zd %s\\n\", r, buf);\n    memset(buf, 0, sizeof buf);\n    r = read_full(103, buf, 25);\n    printf(\"%zd %s\\n\", r, buf);\n    int p[2];\n    if (pipe(p) != 0) return 1;\n    if (write(p[1], \"hey\", 3) != 3) return 1;\n    close(p[1]);\n    memset(buf, 0, sizeof buf);\n    r = read_full(p[0], buf, 8);\n    printf(\"%zd %s\\n\", r, buf);\n    errno = 0;\n    r = read_full(-1, buf, 4);\n    printf(\"%zd %s\\n\", r, en(errno));\n    printf(\"%d\\n\", src_count(\"EINTR\") > 0);\n    return 0;\n}\n", "expected": ["20 ABCDEFGHIJKLMNOPQRST", "16 UVWXYZ0123456789", "0 0", "-1 EIO", "5 ABCDE", "10 ABCDEFGHIJ", "3 hey", "-1 EBADF", "1"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE -Wl,--wrap=read"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-write-all', 1, 'c', 'write_all: запись без потерь', 'Вызов write тоже может записать меньше, чем просили, или вернуть EINTR. Напишите write_all(fd, buf, n): запишите все n байт в цикле, сдвигая указатель на записанное. EINTR повторяйте. Любую другую ошибку (например, ENOSPC или EAGAIN неблокирующего дескриптора, EPIPE у закрытого канала) верните как -1 с тем же errno; что уже записано, откатывать не надо. При n равном нулю верните 0. Проверка подменяет write (--wrap=write) моделью приёмника с порциями 2, 1, 4, 3 байта, вставками EINTR и сбоями ENOSPC и EAGAIN.', '#include <unistd.h>
#include <errno.h>
#include <stddef.h>
#include <sys/types.h>

/* Записать все n байт в fd. Вернуть 0 при успехе
   или -1 с errno при ошибке. */
int write_all(int fd, const void *buf, size_t n) {
    return -1;
}
', 'Тот же цикл, что и в read_full, но счётчик увеличивается на возвращённое write; write со значением 0 при n > 0 здесь не встречается.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* The model: fake descriptors 100..102 are sinks that accept the portions of a script. */\nstruct sink { char data[256]; size_t len; const int *script; int nsteps, step; };\nstatic struct sink sk[3];\nssize_t __real_write(int fd, const void *buf, size_t n);\nssize_t __wrap_write(int fd, const void *buf, size_t n) {\n    if (fd < 100 || fd > 102) return __real_write(fd, buf, n);\n    struct sink *s = &sk[fd - 100];\n    size_t cap = n;\n    if (s->step < s->nsteps) {\n        int v = s->script[s->step++];\n        if (v == -1) { errno = EINTR; return -1; }\n        if (v == -2) { errno = ENOSPC; return -1; }\n        if (v == -3) { errno = EAGAIN; return -1; }\n        if ((size_t)v < cap) cap = (size_t)v;\n    }\n    memcpy(s->data + s->len, buf, cap);\n    s->len += cap;\n    return (ssize_t)cap;\n}\n\nint main(void) {\n    setup();\n    static const int s0[] = {2, -1, 1, 4, -1, 3};\n    static const int s1[] = {3, -2};\n    static const int s2[] = {5, -3};\n    sk[0].script = s0; sk[0].nsteps = 6;\n    sk[1].script = s1; sk[1].nsteps = 2;\n    sk[2].script = s2; sk[2].nsteps = 2;\n    const char *msg = \"The quick brown fox jumps over the lazy dog\";\n    int r = write_all(100, msg, strlen(msg));\n    printf(\"%d %zu %d\\n\", r, sk[0].len, memcmp(sk[0].data, msg, strlen(msg)) == 0);\n    errno = 0;\n    r = write_all(101, msg, 10);\n    printf(\"%d %s %zu\\n\", r, en(errno), sk[1].len);\n    errno = 0;\n    r = write_all(102, \"0123456789\", 10);\n    printf(\"%d %s %zu\\n\", r, en(errno), sk[2].len);\n    r = write_all(100, \"\", 0);\n    printf(\"%d %zu\\n\", r, sk[0].len);\n    int p[2];\n    if (pipe(p) != 0) return 1;\n    r = write_all(p[1], \"pipe!\", 5);\n    char b[8] = {0};\n    if (read(p[0], b, 7) < 0) return 1;\n    printf(\"%d %s\\n\", r, b);\n    signal(SIGPIPE, SIG_IGN);\n    close(p[0]);\n    errno = 0;\n    r = write_all(p[1], \"x\", 1);\n    printf(\"%d %s\\n\", r, en(errno));\n    errno = 0;\n    r = write_all(-1, \"x\", 1);\n    printf(\"%d %s\\n\", r, en(errno));\n    return 0;\n}\n", "expected": ["0 43 1", "-1 ENOSPC 3", "-1 EAGAIN 5", "0 43", "0 pipe!", "-1 EPIPE", "-1 EBADF"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE -Wl,--wrap=write"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-raw-slurp', 2, 'c', 'Сырой вызов: -errno вместо -1', 'Функция syscall из libc сама возвращает -1 и кладёт причину в errno, а ядро на самом деле отдаёт отрицательный код. Напишите raw_slurp(path, buf, cap): откройте файл через syscall(SYS_openat, AT_FDCWD, path, O_RDONLY | O_CLOEXEC), один раз прочитайте до cap байт через syscall(SYS_read, ...) и закройте через syscall(SYS_close, ...). Верните число прочитанных байт либо -errno первого неудачного вызова (например, -2 для ENOENT). Дескриптор закрывайте при любом исходе, даже если read не удался. Обёртки open, read и close использовать нельзя; на aarch64 нет SYS_open, поэтому берём SYS_openat. Проверка открывает несуществующий путь, каталог (read даёт EISDIR) и путь через обычный файл (ENOTDIR) и следит за утечкой дескрипторов.', '#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <stddef.h>
#include <sys/syscall.h>

/* Открыть path, один раз прочитать до cap байт, закрыть.
   Только через syscall(SYS_openat, ...), SYS_read, SYS_close.
   Вернуть число байт или -errno первого неудачного вызова;
   дескриптор закрыть при любом исходе. */
long raw_slurp(const char *path, char *buf, size_t cap) {
    return -1;
}
', 'long fd = syscall(SYS_openat, AT_FDCWD, path, O_RDONLY | O_CLOEXEC); при fd < 0 верните -errno. Сохраните errno из read до вызова close.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\nstatic void put(const char *path, const char *data) {\n    int fd = open(path, O_CREAT | O_TRUNC | O_WRONLY, 0644);\n    if (fd >= 0) {\n        if (write(fd, data, strlen(data)) < 0) {}\n        close(fd);\n    }\n}\nstatic int probe(void) { int f = open(\"/dev/null\", O_RDONLY); close(f); return f; }\n\nint main(void) {\n    setup();\n    char *d = mktmp();\n    char file[96], sub[96], under[96];\n    snprintf(file, sizeof file, \"%s/note.txt\", d);\n    snprintf(sub, sizeof sub, \"%s/sub\", d);\n    snprintf(under, sizeof under, \"%s/note.txt/x\", d);\n    put(file, \"hello syscalls\\n\");\n    mkdir(sub, 0755);\n    int before = probe();\n    char buf[64];\n    memset(buf, 0, sizeof buf);\n    long r = raw_slurp(file, buf, sizeof buf - 1);\n    printf(\"%ld %s\", r, buf);\n    printf(\"%ld\\n\", raw_slurp(file, buf, 5));\n    printf(\"%ld\\n\", raw_slurp(file, buf, 0));\n    printf(\"%ld\\n\", raw_slurp(\"/no/such/file\", buf, 8));\n    printf(\"%ld\\n\", raw_slurp(sub, buf, 8));\n    printf(\"%ld\\n\", raw_slurp(under, buf, 8));\n    printf(\"%d\\n\", probe() == before);\n    printf(\"%d\\n\", src_count(\"syscall(\") >= 3);\n    printf(\"%d\\n\", src_count(\" open(\") + src_count(\"\\topen(\") + src_count(\"(open(\") + src_count(\" read(\") + src_count(\"\\tread(\")\n           + src_count(\"(read(\") + src_count(\" close(\") + src_count(\"\\tclose(\") + src_count(\"(close(\") == 0);\n    return 0;\n}\n", "expected": ["15 hello syscalls", "5", "0", "-2", "-21", "-20", "1", "1", "1"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-load-text', 3, 'c', 'Очистка без потери errno', 'Напишите load_text(path, buf, cap): откройте файл через open(path, O_RDONLY | O_CLOEXEC), один раз прочитайте до cap-1 байт, поставьте в конце нулевой байт и закройте файл. Верните число прочитанных байт либо -1 с errno ПЕРВОГО сбоя. Главная ловушка: если read не удался, а потом close в очистке тоже вернул ошибку, errno окажется от close; причину надо сохранить и восстановить. Если read прошёл, а close вернул ошибку, верните -1 с errno от close (так на сетевых файловых системах проявляется отложенная ошибка записи). Проверка подменяет open, read и close (--wrap) моделью из четырёх виртуальных файлов: рабочий, с ошибкой read (EIO), с ошибкой close (EIO) и недоступный (EACCES), и считает, сколько дескрипторов осталось открытыми.', '#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <stddef.h>

/* Открыть path, один раз прочитать до cap-1 байт, поставить в конце
   нуль, закрыть. Вернуть число байт или -1 с errno ПЕРВОГО сбоя.
   Дескриптор закрывать при любом исходе; отказ close не должен
   затирать причину раньше случившейся ошибки. Если сбоит только
   close, верните -1 и его errno. */
int load_text(const char *path, char *buf, size_t cap) {
    return -1;
}
', 'В ветке ошибки read: int saved = errno; close(fd); errno = saved; return -1;', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* The model of three files and of the descriptor table (100+). */\nstatic int is_open[4];\nstatic int opens, closes;\nssize_t __real_read(int fd, void *buf, size_t n);\nint __real_close(int fd);\nint __real_open(const char *path, int flags, ...);\nint __wrap_open(const char *path, int flags, ...) {\n    if (strncmp(path, \"/fake/\", 6) != 0) return __real_open(path, flags, 0);\n    int k;\n    if (strcmp(path, \"/fake/ok\") == 0) k = 0;\n    else if (strcmp(path, \"/fake/rdfail\") == 0) k = 1;\n    else if (strcmp(path, \"/fake/clfail\") == 0) k = 2;\n    else if (strcmp(path, \"/fake/denied\") == 0) { errno = EACCES; return -1; }\n    else { errno = ENOENT; return -1; }\n    if (!(flags & O_CLOEXEC)) { errno = EINVAL; return -1; }\n    is_open[k] = 1;\n    opens++;\n    return 100 + k;\n}\nssize_t __wrap_read(int fd, void *buf, size_t n) {\n    if (fd < 100 || fd > 103) return __real_read(fd, buf, n);\n    if (!is_open[fd - 100]) { errno = EBADF; return -1; }\n    if (fd == 101) { errno = EIO; return -1; }\n    const char *t = \"mode=fast\";\n    size_t len = strlen(t);\n    if (len > n) len = n;\n    memcpy(buf, t, len);\n    return (ssize_t)len;\n}\nint __wrap_close(int fd) {\n    if (fd < 100 || fd > 103) return __real_close(fd);\n    if (!is_open[fd - 100]) { errno = EBADF; return -1; }\n    is_open[fd - 100] = 0;\n    closes++;\n    if (fd == 101) { errno = EBADF; return -1; }  /* a second error, to catch a clobbered errno */\n    if (fd == 102) { errno = EIO; return -1; }\n    return 0;\n}\n\nstatic void show(const char *path, size_t cap) {\n    char buf[32];\n    memset(buf, ''#'', sizeof buf);\n    buf[31] = 0;\n    errno = 0;\n    int r = load_text(path, buf, cap);\n    if (r < 0) printf(\"%d %s leaked=%d\\n\", r, en(errno), opens - closes);\n    else printf(\"%d [%s] leaked=%d\\n\", r, buf, opens - closes);\n}\n\nint main(void) {\n    setup();\n    show(\"/fake/ok\", 32);\n    show(\"/fake/ok\", 5);\n    show(\"/fake/rdfail\", 32);\n    show(\"/fake/clfail\", 32);\n    show(\"/fake/denied\", 32);\n    show(\"/fake/missing\", 32);\n    printf(\"%d\\n\", src_count(\"errno\") > 0);\n    return 0;\n}\n", "expected": ["9 [mode=fast] leaked=0", "4 [mode] leaked=0", "-1 EIO leaked=0", "-1 EIO leaked=0", "-1 EACCES leaked=0", "-1 ENOENT leaked=0", "1"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE -Wl,--wrap=open,--wrap=read,--wrap=close"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-redirect', 4, 'c', 'Перенаправление вывода через dup2', 'Напишите run_redirected(path, fn): вызовите fn() так, чтобы всё, что она пишет в дескриптор 1 (write(1, ...)), попало в файл path. Файл создайте или обнулите (O_CREAT | O_TRUNC, права 0644). Старый дескриптор 1 сохраните через dup, подмените его через dup2, а после fn() верните на место и закройте лишние дескрипторы: сразу после вызова следующий open должен дать тот же номер, что и до него. Вернёте 0 при успехе и -1, если файл открыть не удалось (стандартный вывод при этом остаётся нетронутым). Использовать freopen нельзя. Проверка работает с настоящими файлами, всё, что программа печатает, на английском.', '#include <unistd.h>
#include <fcntl.h>

/* Выполнить fn() так, чтобы всё, что она пишет в дескриптор 1,
   попало в файл path (создать или обнулить, права 0644).
   После возврата дескриптор 1 снова должен быть прежним терминалом
   (каналом), а лишние дескрипторы закрыты. Вернуть 0 или -1. */
int run_redirected(const char *path, void (*fn)(void)) {
    return -1;
}
', 'open → dup(1) → dup2(fd, 1) → close(fd) → fn() → dup2(saved, 1) → close(saved). Ошибки на промежуточных шагах: закройте то, что уже открыли.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\nstatic void put(const char *path, const char *data) {\n    int fd = open(path, O_CREAT | O_TRUNC | O_WRONLY, 0644);\n    if (fd >= 0) {\n        if (write(fd, data, strlen(data)) < 0) {}\n        close(fd);\n    }\n}\nstatic void get(const char *path, char *out, size_t cap) {\n    int fd = open(path, O_RDONLY);\n    ssize_t n = fd >= 0 ? read(fd, out, cap - 1) : 0;\n    out[n < 0 ? 0 : n] = 0;\n    if (fd >= 0) close(fd);\n}\nstatic int probe(void) { int f = open(\"/dev/null\", O_RDONLY); close(f); return f; }\nstatic void hello(void) {\n    if (write(1, \"hello \", 6) < 0) {}\n    if (write(1, \"world\\n\", 6) < 0) {}\n}\nstatic void quiet(void) {}\n\nint main(void) {\n    setup();\n    char *d = mktmp();\n    char path[96], bad[96], out[128];\n    snprintf(path, sizeof path, \"%s/out.txt\", d);\n    snprintf(bad, sizeof bad, \"%s/no/dir/out.txt\", d);\n    put(path, \"OLDOLDOLDOLDOLDOLD\");\n    int before = probe();\n    int r = run_redirected(path, hello);\n    printf(\"%d\\n\", r);\n    get(path, out, sizeof out);\n    printf(\"[%s]\\n\", out);\n    printf(\"after: stdout is back\\n\");\n    printf(\"%d\\n\", probe() == before);\n    r = run_redirected(path, quiet);\n    get(path, out, sizeof out);\n    printf(\"%d [%s]\\n\", r, out);\n    r = run_redirected(bad, hello);\n    printf(\"%d\\n\", r);\n    printf(\"%d\\n\", probe() == before);\n    printf(\"%d\\n\", src_count(\"dup2(\") + src_count(\"dup3(\") + src_count(\"fcntl(\") > 0);\n    printf(\"%d\\n\", src_count(\"freopen\") == 0);\n    return 0;\n}\n", "expected": ["0", "[hello world", "]", "after: stdout is back", "1", "0 []", "-1", "1", "1", "1"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-open-flags', 5, 'c', 'Флаги open и umask', 'Напишите две функции. open_new(path) создаёт НОВЫЙ файл только для записи с правами 0600 и флагом закрытия при exec; если файл уже существует, вызов обязан завершиться ошибкой EEXIST (проверка существования и создание должны быть одним действием ядра, а не парой access и open). open_log(path) открывает журнал только для записи: создаёт его при отсутствии с правами 0640, а каждая запись должна попадать в конец файла, даже если дескрипторов на него несколько; флаг закрытия при exec тоже обязателен. Итоговые права файла ядро считает как mode & ~umask, проверка меняет umask между вызовами. Обе функции возвращают дескриптор или -1.', '#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

/* Создать НОВЫЙ файл для записи, права 0600, закрывать при exec.
   Если файл уже есть, вернуть -1 (errno = EEXIST). */
int open_new(const char *path) {
    return -1;
}

/* Открыть журнал только для дозаписи: создать при отсутствии (права 0640),
   каждая запись попадает в конец, закрывать при exec. */
int open_log(const char *path) {
    return -1;
}
', 'O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC и O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC; права идут третьим аргументом open.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\nstatic int bits(int fd) {\n    struct stat st;\n    if (fstat(fd, &st) != 0) return -1;\n    return (int)(st.st_mode & 0777);\n}\nstatic void describe(const char *tag, int fd) {\n    if (fd < 0) { printf(\"%s fail %s\\n\", tag, en(errno)); return; }\n    int fl = fcntl(fd, F_GETFL);\n    printf(\"%s mode=%03o acc=%s append=%d cloexec=%d\\n\", tag, bits(fd),\n           (fl & O_ACCMODE) == O_WRONLY ? \"wo\" : \"other\", (fl & O_APPEND) != 0,\n           (fcntl(fd, F_GETFD) & FD_CLOEXEC) != 0);\n}\n\nint main(void) {\n    setup();\n    char *d = mktmp();\n    char a[96], b[96], c[96], nodir[96];\n    snprintf(a, sizeof a, \"%s/a\", d);\n    snprintf(b, sizeof b, \"%s/b\", d);\n    snprintf(c, sizeof c, \"%s/c\", d);\n    snprintf(nodir, sizeof nodir, \"%s/no/x\", d);\n    umask(022);\n    int fd = open_new(a);\n    describe(\"new\", fd);\n    errno = 0;\n    describe(\"again\", open_new(a));\n    errno = 0;\n    describe(\"nodir\", open_new(nodir));\n    umask(027);\n    int l1 = open_log(b);\n    describe(\"log\", l1);\n    umask(077);\n    describe(\"log2\", open_log(c));\n    int l2 = open_log(b);\n    if (write(l1, \"AAA\", 3) != 3 || write(l2, \"BB\", 2) != 2 || write(l1, \"C\", 1) != 1) return 1;\n    char buf[16] = {0};\n    int rf = open(b, O_RDONLY);\n    if (read(rf, buf, 15) < 0) return 1;\n    printf(\"[%s]\\n\", buf);\n    return 0;\n}\n", "expected": ["new mode=600 acc=wo append=0 cloexec=1", "again fail EEXIST", "nodir fail ENOENT", "log mode=640 acc=wo append=1 cloexec=1", "log2 mode=600 acc=wo append=1 cloexec=1", "[AAABBC]"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-tail-bytes', 6, 'c', 'tail: хвост файла с бюджетом вызовов', 'Напишите tail_bytes(fd, k, out): скопируйте в out последние k байт файла (весь файл, если он короче) и верните число байт или -1. Файл может весить мегабайты, поэтому читать его с начала нельзя: используйте lseek(fd, 0, SEEK_END), чтобы узнать размер, и pread (или lseek и read) для нужного хвоста. Модель ядра (--wrap=lseek,read,pread) отдаёт за вызов не больше 4096 байт, считает вызовы и переданные байты: число вызовов не должно превышать 2 + ceil(хвост / 4096), а байт нельзя передавать больше, чем размер хвоста. Модель содержит файл размером миллион байт и пустой файл; k может быть больше размера файла.', '#include <unistd.h>
#include <errno.h>
#include <stddef.h>
#include <sys/types.h>

/* Скопировать в out последние k байт файла fd (весь файл, если он
   короче k). Вернуть число байт или -1. Файл может быть огромным:
   читать только нужный хвост, число системных вызовов должно расти
   с размером хвоста, а не файла. */
long tail_bytes(int fd, size_t k, char *out) {
    return -1;
}
', 'Размер = lseek(fd, 0, SEEK_END); want = min(k, size); читайте pread(fd, out + got, want - got, size - want + got) в цикле, пока got < want.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* The model: fake descriptors 100 (1 000 000 bytes) and 101 (empty). A call moves at most 4096 bytes.\n   byte(i) = ''a'' + (i * 7 + i / 13) % 26. The model counts calls and the bytes handed over. */\nstatic const long SIZES[2] = {1000000, 0};\nstatic long cur[2];\nstatic long calls, moved;\nstatic char byte_at(long i) { return (char)(''a'' + (i * 7 + i / 13) % 26); }\noff_t __real_lseek(int fd, off_t off, int whence);\nssize_t __real_read(int fd, void *buf, size_t n);\nssize_t __real_pread(int fd, void *buf, size_t n, off_t off);\noff_t __wrap_lseek(int fd, off_t off, int whence) {\n    if (fd < 100 || fd > 101) return __real_lseek(fd, off, whence);\n    calls++;\n    int k = fd - 100;\n    long base = whence == SEEK_SET ? 0 : whence == SEEK_CUR ? cur[k] : SIZES[k];\n    if (whence != SEEK_SET && whence != SEEK_CUR && whence != SEEK_END) { errno = EINVAL; return -1; }\n    if (base + off < 0) { errno = EINVAL; return -1; }\n    cur[k] = base + off;\n    return cur[k];\n}\nstatic ssize_t serve(int k, void *buf, size_t n, long pos) {\n    long left = SIZES[k] - pos;\n    long cnt = left < 0 ? 0 : left;\n    if ((long)n < cnt) cnt = (long)n;\n    if (cnt > 4096) cnt = 4096;\n    for (long i = 0; i < cnt; i++) ((char *)buf)[i] = byte_at(pos + i);\n    moved += cnt;\n    return cnt;\n}\nssize_t __wrap_read(int fd, void *buf, size_t n) {\n    if (fd < 100 || fd > 101) return __real_read(fd, buf, n);\n    calls++;\n    ssize_t r = serve(fd - 100, buf, n, cur[fd - 100]);\n    cur[fd - 100] += r;\n    return r;\n}\nssize_t __wrap_pread(int fd, void *buf, size_t n, off_t off) {\n    if (fd < 100 || fd > 101) return __real_pread(fd, buf, n, off);\n    calls++;\n    return serve(fd - 100, buf, n, off);\n}\n\nstatic char out[1100000];\n\nstatic void tail(const char *tag, int fd, size_t k) {\n    calls = 0; moved = 0;\n    long r = tail_bytes(fd, k, out);\n    long size = SIZES[fd - 100];\n    long want = (long)k < size ? (long)k : size;\n    int ok = r == want;\n    for (long i = 0; ok && i < want; i++) ok = out[i] == byte_at(size - want + i);\n    long budget = 2 + (want + 4095) / 4096;\n    printf(\"%s %ld content=%d budget=%d bytes=%d\\n\", tag, r, ok, calls <= budget, moved <= want);\n}\n\nint main(void) {\n    setup();\n    tail(\"small\", 100, 10);\n    tail(\"page\", 100, 5000);\n    tail(\"big\", 100, 300000);\n    tail(\"all\", 100, 5000000);\n    tail(\"empty\", 101, 64);\n    tail(\"zero\", 100, 0);\n    return 0;\n}\n", "expected": ["small 10 content=1 budget=1 bytes=1", "page 5000 content=1 budget=1 bytes=1", "big 300000 content=1 budget=1 bytes=1", "all 1000000 content=1 budget=1 bytes=1", "empty 0 content=1 budget=1 bytes=1", "zero 0 content=1 budget=1 bytes=1"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE -Wl,--wrap=lseek,--wrap=read,--wrap=pread"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-drain', 7, 'c', 'Неблокирующее чтение: EAGAIN и конец', 'Дескриптор fd неблокирующий. Напишите drain(fd, buf, cap, eof): читайте в цикле, пока не случится одно из трёх: данные кончились (read вернул -1 с EAGAIN или EWOULDBLOCK, это не ошибка), наступил конец файла (read вернул 0) или заполнен буфер из cap байт. В *eof запишите 1 только в случае конца файла, иначе 0. Верните число прочитанных байт либо -1 с errno при настоящей ошибке (например, EBADF). EINTR повторяйте. Проверка использует настоящий канал pipe: пустой, с данными, переполняющий буфер и с закрытым концом записи.', '#include <unistd.h>
#include <errno.h>
#include <stddef.h>
#include <sys/types.h>

/* fd неблокирующий. Читать, пока не кончатся данные (EAGAIN), не
   наступит конец файла (read вернул 0) или не заполнится buf (cap байт).
   *eof = 1 только при конце файла, иначе 0. Вернуть число прочитанных
   байт или -1 с errno при настоящей ошибке. EAGAIN ошибкой не считается. */
ssize_t drain(int fd, char *buf, size_t cap, int *eof) {
    return -1;
}
', 'Три разных исхода read < 0: EINTR → continue, EAGAIN → break (не ошибка), иное → return -1. Не просите больше, чем cap - got.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <limits.h>\n#include <signal.h>\n#include <time.h>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/syscall.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic char *mktmp(void) {\n    static char d[64];\n    strcpy(d, \"/tmp/uXXXXXX\");\n    return mkdtemp(d);\n}\n\nstatic const char *en(int e) {\n    switch (e) {\n    case 0: return \"0\";\n    case EINTR: return \"EINTR\";\n    case EIO: return \"EIO\";\n    case EAGAIN: return \"EAGAIN\";\n    case ENOSPC: return \"ENOSPC\";\n    case ENOENT: return \"ENOENT\";\n    case EACCES: return \"EACCES\";\n    case EBADF: return \"EBADF\";\n    case EEXIST: return \"EEXIST\";\n    case EISDIR: return \"EISDIR\";\n    case ENOTDIR: return \"ENOTDIR\";\n    case EINVAL: return \"EINVAL\";\n    case EPIPE: return \"EPIPE\";\n    default: return \"?\";\n    }\n}\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\nstatic void show(int fd, size_t cap) {\n    char buf[64];\n    memset(buf, 0, sizeof buf);\n    int eof = 7;\n    errno = 0;\n    ssize_t r = drain(fd, buf, cap, &eof);\n    if (r < 0) printf(\"%zd %s\\n\", r, en(errno));\n    else printf(\"%zd [%s] eof=%d\\n\", r, buf, eof);\n}\n\nint main(void) {\n    setup();\n    int p[2];\n    if (pipe(p) != 0) return 1;\n    fcntl(p[0], F_SETFL, fcntl(p[0], F_GETFL) | O_NONBLOCK);\n    show(p[0], 32);\n    if (write(p[1], \"abc\", 3) != 3 || write(p[1], \"def\", 3) != 3) return 1;\n    show(p[0], 32);\n    if (write(p[1], \"0123456789ABCDEFGHIJ\", 20) != 20) return 1;\n    show(p[0], 8);\n    show(p[0], 32);\n    show(p[0], 32);\n    if (write(p[1], \"xy\", 2) != 2) return 1;\n    close(p[1]);\n    show(p[0], 32);\n    show(p[0], 32);\n    show(-1, 8);\n    return 0;\n}\n", "expected": ["0 [] eof=0", "6 [abcdef] eof=0", "8 [01234567] eof=0", "12 [89ABCDEFGHIJ] eof=0", "0 [] eof=0", "2 [xy] eof=1", "0 [] eof=1", "-1 EBADF"], "flags": "-std=gnu11 -O1 -g0 -Wall -D_GNU_SOURCE"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-strace-failures', 8, 'func', 'Неудачные вызовы в журнале strace', 'Напишите функцию failed_calls(lines): lines — строки журнала strace (с флагами -f, -tt, -T или без них). Верните список пар (имя вызова, имя errno) для каждого вызова, завершившегося результатом -1 с именем ошибки (E...), в порядке строк. Строка может начинаться с pid в виде «[pid  4242] » или «4242  » и с метки времени «15:14:20.434758 ». Результат стоит в конце строки после «) = », за ним может идти «<0.000012>» (время). Долгий вызов, в середине которого strace напечатал строки других процессов, записан двумя строками: «... <unfinished ...>» (результата нет, пропустите) и «<... read resumed>...) = -1 EINTR (...)», где имя берётся из слов «<... read resumed>». Пропускайте строки сигналов «--- ... ---» и завершения «+++ ... +++», результаты без -1 (в том числе «= ? ERESTART...») и тексты внутри строковых аргументов: «write(2, "x = -1 EIO", 10) = 10» не ошибка.', 'def failed_calls(lines):
    pass
', 'Результат — после последнего вхождения «) = » (rsplit); отрежьте «<...>» в конце; имя вызова ищите регулярным выражением по «<... (\w+) resumed>» или «имя(».', '{"func": "failed_calls", "tests": [{"args": [["openat(AT_FDCWD, \"/etc/app.conf\", O_RDONLY|O_CLOEXEC) = -1 ENOENT (No such file or directory)", "openat(AT_FDCWD, \"/etc/ld.so.cache\", O_RDONLY|O_CLOEXEC) = 3", "read(3, \"\\177ELF\\2\\1\\1\\3\\0\\0\\0\\0\\0\\0\\0\\0\\3\\0>\\0\\1\\0\\0\\0\"..., 832) = 832", "close(3)                                = 0", "exit_group(1)                           = ?", "+++ exited with 1 +++"]], "expected": [{"__tuple__": ["openat", "ENOENT"]}]}, {"args": [["15:14:20.434758 faccessat(AT_FDCWD, \"/etc/ld.so.preload\", R_OK) = -1 ENOENT (No such file or directory) <0.000002>", "15:14:20.434817 openat(AT_FDCWD, \"/etc/ld.so.cache\", O_RDONLY|O_CLOEXEC) = 3 <0.000003>", "15:14:20.435001 mkdir(\"/run/app\", 0755) = -1 EEXIST (File exists) <0.000010>", "15:14:20.435100 ioctl(1, TCGETS, 0x7ffd1a2b3c40) = -1 ENOTTY (Inappropriate ioctl for device) <0.000004>"]], "expected": [{"__tuple__": ["faccessat", "ENOENT"]}, {"__tuple__": ["mkdir", "EEXIST"]}, {"__tuple__": ["ioctl", "ENOTTY"]}]}, {"args": [["[pid  4242] poll([{fd=5, events=POLLIN}], 1, -1 <unfinished ...>", "[pid  4243] read(5, 0x7ffd1a2b3c4d, 4096) = -1 EAGAIN (Resource temporarily unavailable) <0.000012>", "[pid  4242] <... poll resumed>)     = 1 ([{fd=5, revents=POLLIN}]) <0.512345>", "[pid  4243] read(6,  <unfinished ...>", "--- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_EXITED, si_pid=4244, si_uid=0, si_status=0, si_utime=0, si_stime=0} ---", "[pid  4243] <... read resumed>0x7ffd1a2b3c4d, 4096) = -1 EINTR (Interrupted system call) <0.003100>", "[pid  4244] +++ exited with 0 +++"]], "expected": [{"__tuple__": ["read", "EAGAIN"]}, {"__tuple__": ["read", "EINTR"]}]}, {"args": [["4242  15:14:20.5 write(2, \"open(\\\"/x\\\") = -1 ENOENT\\n\", 24) = 24 <0.000010>", "4242  15:14:20.6 connect(3, {sa_family=AF_INET, sin_port=htons(443), sin_addr=inet_addr(\"10.0.0.5\")}, 16) = -1 EINPROGRESS (Operation now in progress) <0.000050>", "4243  15:14:20.7 clock_nanosleep(CLOCK_REALTIME, 0, {tv_sec=1, tv_nsec=0}, 0x7ffc1c2d0a10) = ? ERESTART_RESTARTBLOCK (Interrupted by signal) <0.100000>", "4243  15:14:20.8 write(1, \"x) = -1 EIO\\n\", 12) = 12", "4243  15:14:21.0 openat(AT_FDCWD, \"/root/.ssh/id_rsa\", O_RDONLY) = -1 EACCES (Permission denied)"]], "expected": [{"__tuple__": ["connect", "EINPROGRESS"]}, {"__tuple__": ["openat", "EACCES"]}]}, {"args": [["openat(AT_FDCWD</>, \"/var/log/app.log\", O_WRONLY|O_APPEND) = 4</var/log/app.log> <0.000020>", "write(4</var/log/app.log>, \"done\\n\", 5) = -1 ENOSPC (No space left on device) <0.000030>", "close(4</var/log/app.log>) = -1 EIO (Input/output error) <0.000009>", "epoll_wait(7<anon_inode:[eventpoll]>, [], 64, 0) = 0 <0.000002>", "read(0<pipe:[12345]>, \"\", 4096) = 0 <0.000003>", "lseek(0<pipe:[12345]>, 0, SEEK_CUR) = -1 ESPIPE (Illegal seek) <0.000002>"]], "expected": [{"__tuple__": ["write", "ENOSPC"]}, {"__tuple__": ["close", "EIO"]}, {"__tuple__": ["lseek", "ESPIPE"]}]}, {"args": [[]], "expected": []}, {"args": [["openat(AT_FDCWD, \"/etc/app.conf\", O_RDONLY|O_CLOEXEC) = -1 ENOENT (No such file or directory)", "openat(AT_FDCWD, \"/etc/ld.so.cache\", O_RDONLY|O_CLOEXEC) = 3", "read(3, \"\\177ELF\\2\\1\\1\\3\\0\\0\\0\\0\\0\\0\\0\\0\\3\\0>\\0\\1\\0\\0\\0\"..., 832) = 832", "close(3)                                = 0", "exit_group(1)                           = ?", "+++ exited with 1 +++", "[pid  4242] poll([{fd=5, events=POLLIN}], 1, -1 <unfinished ...>", "[pid  4243] read(5, 0x7ffd1a2b3c4d, 4096) = -1 EAGAIN (Resource temporarily unavailable) <0.000012>", "[pid  4242] <... poll resumed>)     = 1 ([{fd=5, revents=POLLIN}]) <0.512345>", "[pid  4243] read(6,  <unfinished ...>", "--- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_EXITED, si_pid=4244, si_uid=0, si_status=0, si_utime=0, si_stime=0} ---", "[pid  4243] <... read resumed>0x7ffd1a2b3c4d, 4096) = -1 EINTR (Interrupted system call) <0.003100>", "[pid  4244] +++ exited with 0 +++", "openat(AT_FDCWD</>, \"/var/log/app.log\", O_WRONLY|O_APPEND) = 4</var/log/app.log> <0.000020>", "write(4</var/log/app.log>, \"done\\n\", 5) = -1 ENOSPC (No space left on device) <0.000030>", "close(4</var/log/app.log>) = -1 EIO (Input/output error) <0.000009>", "epoll_wait(7<anon_inode:[eventpoll]>, [], 64, 0) = 0 <0.000002>", "read(0<pipe:[12345]>, \"\", 4096) = 0 <0.000003>", "lseek(0<pipe:[12345]>, 0, SEEK_CUR) = -1 ESPIPE (Illegal seek) <0.000002>"]], "expected": [{"__tuple__": ["openat", "ENOENT"]}, {"__tuple__": ["read", "EAGAIN"]}, {"__tuple__": ["read", "EINTR"]}, {"__tuple__": ["write", "ENOSPC"]}, {"__tuple__": ["close", "EIO"]}, {"__tuple__": ["lseek", "ESPIPE"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 26, 'la26-strace-summary', 9, 'func', 'Таблица strace -c', 'Журнал strace -c — таблица с колонками «% time, seconds, usecs/call, calls, errors, syscall». Колонка errors для вызовов без ошибок пуста, остальные заполнены; заголовок и линии из дефисов не данные; последняя строка с именем total (может отсутствовать) содержит общие числа. Напишите strace_summary(lines) и верните кортеж (всего вызовов, всего ошибок, список_с_ошибками, самый_частый): общие числа берутся из строки total, а если её нет, это суммы по строкам; список_с_ошибками — пары (имя, ошибок) только для вызовов, у которых были ошибки, по убыванию числа ошибок, при равенстве по имени; самый_частый — имя вызова с наибольшим calls (при равенстве первое по алфавиту) или None, если данных нет.', 'def strace_summary(lines):
    pass
', 'Разбейте строку split(): в строке с ошибками 6 слов, без ошибок 5; имя — последнее слово. Строки, начинающиеся с «%» или «-», пропускайте.', '{"func": "strace_summary", "tests": [{"args": [["% time     seconds  usecs/call     calls    errors syscall", "------ ----------- ----------- --------- --------- ----------------", " 77.88    0.000264         264         1           execve", "  7.96    0.000027           5         5           write", "  4.72    0.000016           4         4         1 openat", "  2.65    0.000009           1         8           mmap", "  0.59    0.000002           0         5           close", "  0.29    0.000001           1         1         1 faccessat", "------ ----------- ----------- --------- --------- ----------------", "100.00    0.000319           9        24         2 total"]], "expected": {"__tuple__": [24, 2, [{"__tuple__": ["faccessat", 1]}, {"__tuple__": ["openat", 1]}], "mmap"]}}, {"args": [["% time     seconds  usecs/call     calls    errors syscall", "------ ----------- ----------- --------- --------- ----------------", " 50.00    0.010000         100       100        40 read", " 30.00    0.006000          60       100         7 futex", " 20.00    0.004000          40        50        40 epoll_wait", " 10.00    0.002000          20        50           write", "------ ----------- ----------- --------- --------- ----------------", "100.00    0.022000          73       300        87 total"]], "expected": {"__tuple__": [300, 87, [{"__tuple__": ["epoll_wait", 40]}, {"__tuple__": ["read", 40]}, {"__tuple__": ["futex", 7]}], "futex"]}}, {"args": [["% time     seconds  usecs/call     calls    errors syscall", "------ ----------- ----------- --------- --------- ----------------", " 60.00    0.000300          30        10           read", " 40.00    0.000200          20        10           write"]], "expected": {"__tuple__": [20, 0, [], "read"]}}, {"args": [["% time     seconds  usecs/call     calls    errors syscall", "------ ----------- ----------- --------- --------- ----------------", "100.00    0.000100          10         9         2 stat", "  0.00    0.000000           0         9         2 access", "  0.00    0.000000           0         3           brk"]], "expected": {"__tuple__": [21, 4, [{"__tuple__": ["access", 2]}, {"__tuple__": ["stat", 2]}], "access"]}}, {"args": [["% time     seconds  usecs/call     calls    errors syscall", "------ ----------- ----------- --------- --------- ----------------", "------ ----------- ----------- --------- --------- ----------------", "100.00    0.000000           0         0           total"]], "expected": {"__tuple__": [0, 0, [], null]}}, {"args": [[]], "expected": {"__tuple__": [0, 0, [], null]}}]}');
